## Code Example
```javascript
// Pseudo test outline using Jest-like syntax
function testDedupAndWrite(db, queue) {
  const events = [{id: 'e1'}, {id: 'e1'}]; // duplicate
  queue.publish(events[0]);
  queue.publish(events[1]);
  processOnce();
  if (db.count('summary', 'e1') !== 1) throw new Error('duplicate write');
}
```

